def standard():
    from itertools import product
    n = 0
    for t in product(range(3), repeat=8):
        if sum(t) != 6 or t.count(2) != 2:
            continue
        ok = True
        for i in range(8):
            if t[i] == 2:
                for j in (i - 1, i + 1):
                    if 0 <= j < 8 and t[j] != 0:
                        ok = False
        n += ok
    return n

def unique():
    return [standard()]
